mapper.select:
SELECT d.*, u.real_name AS operator_name
FROM quality_defect_dispose d LEFT JOIN sys_user u ON u.id = d.operator_id
WHERE d.id = #{id}

mapper.update:
UPDATE quality_defect_dispose
verify_status = #{verifyStatus}, verify_comment = #{verifyComment}, verify_at = #{verifyAt},
WHERE id = #{id}
